solution.exercise.c:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
uint64_t private_key(uint64_t p, uint64_t *s) {
    if (p <= 2)
        return 0;
    *s = *s * 6364136223846793005ULL + 1442695040888963407ULL;
    return 2 + (*s >> 1) % (p - 2);
}
static uint64_t mul(uint64_t a, uint64_t b, uint64_t m) {
    uint64_t r = 0;
    while (b) {
        if (b & 1)
            r = r >= m - a ? r - (m - a) : r + a;
        b >>= 1;
        a = a >= m - a ? a - (m - a) : a + a;
    }
    return r;
}
uint64_t public_key(uint64_t p, uint64_t g, uint64_t k) {
    if (p < 2)
        return 0;
    uint64_t r = 1;
    g %= p;
    while (k) {
        if (k & 1)
            r = mul(r, g, p);
        g = mul(g, g, p);
        k >>= 1;
    }
    return r;
}
uint64_t secret(uint64_t p, uint64_t g, uint64_t k) { return public_key(p, g, k); }

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    uint64_t rng = 123;
    for (int i = 0; i < 100; i++) {
        uint64_t k = private_key(23, &rng);
        assert(k > 1 && k < 23);
    }
    assert(public_key(23, 5, 6) == 8);
    assert(public_key(23, 5, 15) == 19);
    assert(secret(23, 19, 6) == 2);
    assert(secret(23, 8, 15) == 2);
    assert(public_key(23, 5, 0) == 1);

    return 0;
}
